class Solution {public:vector<vector<int>> supersequences(vector<string>& words){
 int active=0;vector<int> adj(26);for(auto&w:words){int a=w[0]-'a',b=w[1]-'a';active|=1<<a;active|=1<<b;adj[a]|=1<<b;}
 vector<int>letters;for(int i=0;i<26;++i)if(active>>i&1)letters.push_back(i);int a=letters.size(),best=a+1;vector<vector<int>>ans;
 for(int mask=0;mask<(1<<a);++mask){int cnt=__builtin_popcount((unsigned)mask);if(cnt>best)continue;
 int indeg[26]={};bool kept[26]={};for(int j=0;j<a;++j)if(!(mask>>j&1))kept[letters[j]]=true;
 for(int i:letters)if(kept[i])for(int j:letters)if(kept[j]&&(adj[i]>>j&1))++indeg[j];
 queue<int>q;for(int i:letters)if(kept[i]&&!indeg[i])q.push(i);int seen=0;
 while(!q.empty()){int u=q.front();q.pop();++seen;for(int v:letters)if(kept[v]&&(adj[u]>>v&1)&&!--indeg[v])q.push(v);}
 if(seen!=a-cnt)continue;if(cnt<best){best=cnt;ans.clear();}
 vector<int>freq(26);for(int i:letters)freq[i]=1;for(int j=0;j<a;++j)if(mask>>j&1)++freq[letters[j]];ans.push_back(freq);
 }return ans;
}};
